{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfd;--muted:#61707a;--accent:#5b8c7a;--accent-2:#7a5b8c;--card:#ffffff;--glass:rgba(255,255,255,0.6);font-family:Inter, ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial}
    *{box-sizing:border-box}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#f3f6f8);color:#122;line-height:1.45}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(90deg,rgba(88,110,128,0.03),transparent);backdrop-filter:blur(4px)}
    .brand{font-weight:700;letter-spacing:0.2px}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-weight:600}
    .wrap{max-width:980px;margin:28px auto;padding:20px}

    /* Pattern (inline SVG via <svg> element) */
    .hero{position:relative;padding:36px;border-radius:14px;background-image:radial-gradient(circle at 10% 10%, rgba(90,110,130,0.04), transparent 20%), linear-gradient(180deg,#fff,#fbfdff);box-shadow:0 6px 18px rgba(17,24,31,0.06);overflow:hidden}
    .hero .title{display:flex;justify-content:space-between;align-items:center}
    h1{margin:0;font-size:1.6rem}
    p.lead{margin:8px 0 0;color:var(--muted)}

    /* Pricing comparator */
    .comparator{display:flex;gap:16px;margin-top:22px;align-items:center}
    .switch{background:var(--card);border-radius:999px;padding:6px;border:1px solid rgba(17,24,31,0.06);display:flex}
    .switch button{background:transparent;border:0;padding:8px 12px;border-radius:999px;cursor:pointer;font-weight:600;color:var(--muted)}
    .switch button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;box-shadow:0 6px 16px rgba(90,90,90,0.08)}
    .price-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-left:12px}
    .plan{background:var(--card);padding:16px;border-radius:10px;min-height:80px;display:flex;flex-direction:column;justify-content:space-between;border:1px solid rgba(17,24,31,0.04)}
    .plan .label{font-weight:700;color:#1b2b2f}
    .plan .amount{font-size:1.4rem;font-weight:800;color:var(--accent);transition:transform .25s}
    .muted{color:var(--muted);font-size:0.9rem}

    /* Mood-to-Method */
    .mood{display:flex;gap:10px;margin-top:22px;flex-wrap:wrap}
    .mood button{border:1px solid rgba(17,24,31,0.06);background:transparent;padding:8px 12px;border-radius:999px;cursor:pointer;font-weight:600;color:var(--muted)}
    .mood button.active{background:var(--accent);color:#fff;border-color:transparent}
    .recommend{margin-top:18px;padding:16px;border-radius:10px;background:linear-gradient(180deg,#fff,#fbfbff);border:1px solid rgba(17,24,31,0.04)}
    .cta{margin-top:16px}
    .btn{display:inline-block;background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:700}

    footer{margin-top:26px;padding:18px 20px;border-radius:10px;background:linear-gradient(90deg,rgba(124,140,160,0.02),transparent)}
    .legal{font-size:0.85rem;color:var(--muted)}

    @media(min-width:860px){
      .wrap{padding:40px}
      .price-grid{grid-template-columns:repeat(3,1fr)}
    }
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Who I am</a>
      <a href="specialties.html">Areas</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Invest</a>
      <a href="faq.html">Help</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero" aria-labelledby="invest">
      <!-- decorative SVG pattern -->
      <svg width="0" height="0" style="position:absolute;left:-9999px;">
        <defs>
          <pattern id="p1" x="0" y="0" width="24" height="24" patternUnits="userSpaceOnUse">
            <rect x="0" y="0" width="24" height="24" fill="#fff"/>
            <circle cx="4" cy="4" r="1.6" fill="#e9f4f2" />
            <circle cx="20" cy="20" r="1.6" fill="#f6eef8" />
            <path d="M12 0v24" stroke="#eef5f3" stroke-width="0.5"/>
          </pattern>
        </defs>
      </svg>

      <div class="title">
        <div>
          <h1 id="invest">Investment & Session Options</h1>
          <p class="lead">Practical formats for focused work or ongoing support. Pick the rhythm that feels sustainable.</p>
        </div>
        <div style="text-align:right;color:var(--muted)">
          <div style="font-size:0.95rem;font-weight:700">{{CITY}}, {{STATE}}</div>
          <div style="font-size:0.9rem;margin-top:6px">{{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        </div>
      </div>

      <div class="comparator" aria-hidden="false">
        <div class="switch" role="tablist" aria-label="Pricing view">
          <button id="mode-monthly" class="active" aria-pressed="true">Per session</button>
          <button id="mode-package" aria-pressed="false">Session bundle</button>
        </div>

        <div class="price-grid" id="prices">
          <div class="plan">
            <div class="label">Single Session</div>
            <div class="amount" data-monthly="150" data-package="140">$150</div>
            <div class="muted">60 minutes, focused check-in</div>
          </div>

          <div class="plan">
            <div class="label">Focus Series</div>
            <div class="amount" data-monthly="145" data-package="125">$145</div>
            <div class="muted">6-session arc, best for a targeted goal</div>
          </div>

          <div class="plan">
            <div class="label">Steady Support</div>
            <div class="amount" data-monthly="120" data-package="100">$120</div>
            <div class="muted">Monthly cadence—reliable continuity</div>
          </div>
        </div>
      </div>

      <div class="mood" aria-label="Current state selector">
        <button data-key="overwhelmed">Overwhelmed</button>
        <button data-key="stuck">Stuck</button>
        <button data-key="disconnected">Disconnected</button>
        <button data-key="curious">Curious</button>
      </div>

      <div class="recommend" id="recommendation" aria-live="polite">
        <strong>Recommended approach</strong>
        <p id="rec-text" class="muted" style="margin:8px 0 0">Choose how you're feeling above to see a suggested starting point and the next steps. This is a suggestion to discuss—no commitments required.</p>
        <div class="cta">
          <a id="primary-cta" class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>

    </section>

    <footer>
      <div class="legal">
        Confidentiality note: Conversations are confidential within legal and ethical limits. Therapeutic work focuses on emotional and behavioral goals—not medical treatment. If you are in immediate crisis, call local emergency services or the crisis line in your area.
      </div>
    </footer>
  </main>

  <script>
    // Pricing comparator (animated number tween)
    (function(){
      const monthlyBtn = document.getElementById('mode-monthly');
      const packageBtn = document.getElementById('mode-package');
      const amounts = Array.from(document.querySelectorAll('.plan .amount'));
      let mode = 'monthly';

      function format(n){return '$' + Math.round(n)}
      function animate(el, from, to){
        const start = performance.now();
        const dur = 420;
        (function tick(now){
          const t = Math.min(1,(now-start)/dur);
          const ease = (--t)*t*t+1; // ease out
          const val = from + (to-from)*ease;
          el.textContent = format(val);
          el.style.transform = 'translateY('+ (1-ease)*6 +'px)';
          if(now-start < dur) requestAnimationFrame(tick);
          else el.style.transform = '';
        })(start);
      }

      function setMode(newMode){
        if(mode === newMode) return;
        mode = newMode;
        monthlyBtn.classList.toggle('active', mode==='monthly');
        packageBtn.classList.toggle('active', mode==='package');
        monthlyBtn.setAttribute('aria-pressed', mode==='monthly');
        packageBtn.setAttribute('aria-pressed', mode==='package');
        amounts.forEach(a=>{
          const from = parseFloat(a.textContent.replace('$','')) || 0;
          const to = parseFloat(a.dataset[newMode]) || from;
          animate(a, from, to);
        });
      }

      monthlyBtn.addEventListener('click', ()=> setMode('monthly'));
      packageBtn.addEventListener('click', ()=> setMode('package'));
    })();

    // Mood-to-Method selector
    (function(){
      const buttons = Array.from(document.querySelectorAll('.mood button'));
      const recText = document.getElementById('rec-text');
      const cta = document.getElementById('primary-cta');

      const map = {
        overwhelmed: {title:'Short, grounding sessions', desc:'Begin with practical breathing & planning; 30–50 minute sessions to reduce immediate overwhelm and prioritize next steps.', cta:'{{PRIMARY_CTA_LABEL}} — Start with a brief consult'},
        stuck: {title:'A targeted series', desc:'A focused 6-week sequence to identify blocks, experiment with small changes, and track what shifts.', cta:'{{PRIMARY_CTA_LABEL}} — Book a Focus Series'},
        disconnected: {title:'Relational tuning', desc:'Sessions that explore patterns in connection and communication—work at a steady pace to rebuild closeness.', cta:'{{PRIMARY_CTA_LABEL}} — Begin relational work'},
        curious: {title:'Exploratory first session', desc:'A single session to map concerns, set priorities, and outline possible paths forward.', cta:'{{PRIMARY_CTA_LABEL}} — Schedule an exploratory visit'}
      };

      function setActive(key, btn){
        buttons.forEach(b=>b.classList.toggle('active', b===btn));
        const s = map[key];
        recText.innerHTML = '<strong>'+s.title+'</strong><br/>' + s.desc;
        cta.textContent = s.cta;
        // subtle pulse
        cta.animate([{transform:'scale(0.98)'},{transform:'scale(1)'}],{duration:240,easing:'ease-out'});
      }

      buttons.forEach(btn=>btn.addEventListener('click', e=>{
        const key = btn.dataset.key;
        setActive(key, btn);
      }));

      // default
      buttons[0].click();
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--muted:#58646d;--accent:#6a8a76;--card:#fff;font-family:Inter,system-ui,Segoe UI,Roboto,Arial}
    body{margin:0;background:linear-gradient(180deg,#fbfcfd,#f7f9fb);color:#122}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none}
    .wrap{max-width:920px;margin:28px auto;padding:18px}
    h1{font-size:1.5rem;margin:0}
    .intro{color:var(--muted);margin-top:8px}

    .faq-list{margin-top:18px}
    .qa{background:var(--card);border-radius:10px;padding:14px;margin-bottom:10px;border:1px solid rgba(18,34,40,0.04)}
    .q{display:flex;justify-content:space-between;cursor:pointer}
    .q h3{margin:0;font-size:1rem}
    .a{margin-top:10px;color:var(--muted);display:none}
    .q .toggle{color:var(--muted);font-weight:700}

    .note{margin-top:16px;font-size:0.9rem;color:var(--muted)}
    .footer-legal{margin-top:22px;font-size:0.85rem;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Who I am</a>
      <a href="specialties.html">Areas</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Invest</a>
      <a href="faq.html">Help</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Questions people often ask</h1>
    <p class="intro">Straightforward answers about what to expect, how sessions are structured, and practicalities like fees and cancellations.</p>

    <section class="faq-list" id="faq">
      <div class="qa">
        <div class="q" tabindex="0">
          <h3>What happens in a first session?</h3>
          <div class="toggle">+</div>
        </div>
        <div class="a">We usually begin with what brings you now—goals, recent events, and immediate concerns. You'll get a chance to describe your priorities. We often leave time to plan next steps together. Sessions are collaborative and tailored to your pace.</div>
      </div>

      <div class="qa">
        <div class="q" tabindex="0">
          <h3>How long is a session and how often should I come?</h3>
          <div class="toggle">+</div>
        </div>
        <div class="a">Standard sessions are 50–60 minutes. Frequency depends on need—some start weekly for momentum, others move to biweekly for steady maintenance. We'll discuss a rhythm that fits your life and goals.</div>
      </div>

      <div class="qa">
        <div class="q" tabindex="0">
          <h3>Are sessions confidential?</h3>
          <div class="toggle">+</div>
        </div>
        <div class="a">Yes. Information shared in sessions is kept confidential within legal and ethical boundaries. Exceptions include imminent risk of harm, court orders, or where required by law. We'll go over limits of confidentiality on intake.</div>
      </div>

      <div class="qa">
        <div class="q" tabindex="0">
          <h3>What if I need help between sessions or I'm in crisis?</h3>
          <div class="toggle">+</div>
        </div>
        <div class="a">I aim to respond to messages in a timely way, but I do not provide emergency services through email or text. If you are in immediate danger, please call local emergency services or a crisis line. We can discuss safety planning during sessions.</div>
      </div>

      <div class="qa">
        <div class="q" tabindex="0">
          <h3>Payment, cancellations, and insurance</h3>
          <div class="toggle">+</div>
        </div>
        <div class="a">Payment is due at the time of the session. Cancellation policy is 48 hours notice for full refund or reschedule. I provide receipts you may submit to your insurer—check your plan for out-of-network coverage. No medical claims or guarantees are made about outcomes.</div>
      </div>

    </section>

    <div class="note">If your question isn't listed, please reach out at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}}. I'll respond with the best next steps within two business days.</div>

    <div class="footer-legal">
      Clinical boundaries and confidentiality are reviewed during intake. If you are experiencing suicidal thoughts or are a danger to yourself or others, call local emergency services or your local crisis resources immediately.
    </div>

  </main>

  <script>
    // Simple accordion for FAQ
    (function(){
      const items = document.querySelectorAll('.qa');
      items.forEach(item=>{
        const q = item.querySelector('.q');
        const a = item.querySelector('.a');
        q.addEventListener('click', ()=>{
          const open = a.style.display === 'block';
          // close all
          document.querySelectorAll('.qa .a').forEach(x=>x.style.display='none');
          document.querySelectorAll('.qa .toggle').forEach(t=>t.textContent='+');
          if(!open){
            a.style.display='block';
            q.querySelector('.toggle').textContent='−';
          }
        });
        q.addEventListener('keydown', e=>{if(e.key==='Enter' || e.key===' ') q.click();});
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7fbfb;--accent:#6d8c78;--accent-2:#7a5b8c;--card:#fff;--muted:#52606b;font-family:Inter,system-ui,Roboto,Arial}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#fff);color:#122}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 22px}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    .wrap{max-width:980px;margin:28px auto;padding:18px}

    .grid{display:grid;grid-template-columns:1fr;gap:18px}
    .panel{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(18,24,30,0.04)}
    .hero-title{display:flex;justify-content:space-between;align-items:center}
    h1{margin:0;font-size:1.4rem}
    .sub{color:var(--muted);margin-top:8px}

    /* Mood selector prominent here */
    .moods{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}
    .moods button{padding:10px 12px;border-radius:10px;border:1px solid rgba(18,24,30,0.05);background:transparent;cursor:pointer}
    .moods button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;border-color:transparent}

    .summary{display:flex;flex-direction:column;gap:6px;margin-top:12px}
    .summary .row{display:flex;justify-content:space-between;font-weight:700}
    .summary .muted{font-weight:600;color:var(--muted);font-size:0.95rem}

    form{display:flex;flex-direction:column;gap:10px;margin-top:12px}
    input,textarea,select{padding:10px;border-radius:8px;border:1px solid rgba(18,24,30,0.06)}
    .row-flex{display:flex;gap:8px}
    .btn{background:var(--accent);color:#fff;padding:10px;border-radius:10px;text-decoration:none;border:0;font-weight:700;cursor:pointer}

    .disclaimer{margin-top:12px;color:var(--muted);font-size:0.9rem}

    @media(min-width:900px){
      .grid{grid-template-columns:1fr 380px}
    }
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Bio</a>
      <a href="specialties.html">Specialties</a>
      <a href="approach.html">Method</a>
      <a href="fees.html">Rates</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="grid">
      <section class="panel">
        <div class="hero-title">
          <div>
            <h1>Reserve a session</h1>
            <div class="sub">Choose the starting point that fits how you're feeling—I'll follow your pace from there.</div>
          </div>
          <div style="text-align:right;color:var(--muted)">Availability updated weekly</div>
        </div>

        <div class="moods" role="tablist" aria-label="Select how you are feeling">
          <button data-key="overwhelmed">Overwhelmed</button>
          <button data-key="stuck">Stuck</button>
          <button data-key="exhausted">Exhausted</button>
          <button data-key="curious">Curious</button>
        </div>

        <div class="summary" id="summary">
          <div class="row"><div id="method-label">Suggested: Exploratory Visit</div><div id="method-price">$150</div></div>
          <div class="muted" id="method-desc">A single session to map concerns, set priorities, and plan next steps.</div>
        </div>

        <form id="book-form" onsubmit="handleSubmit(event)">
          <input name="name" placeholder="Your name" required>
          <div class="row-flex">
            <input name="email" placeholder="Email" required>
            <input name="phone" placeholder="Phone (optional)">
          </div>
          <label style="font-size:0.9rem;color:var(--muted)">Preferred days / times</label>
          <input name="times" placeholder="e.g. Weekday mornings, Tue/Thu after 6pm">
          <label style="font-size:0.9rem;color:var(--muted)">Anything you'd like me to know?</label>
          <textarea name="notes" rows="4" placeholder="Optional context"></textarea>

          <div style="display:flex;gap:10px;align-items:center;margin-top:6px">
            <button type="submit" class="btn">{{PRIMARY_CTA_LABEL}}</button>
            <a href="mailto:{{EMAIL}}" style="color:var(--muted);text-decoration:none">Or email: {{EMAIL}}</a>
          </div>
        </form>

        <div class="disclaimer">
          Confidentiality and scope: Sessions are confidential with ethical/legal limits. This booking does not replace medical care. If you are in crisis, call emergency services or a local crisis number immediately.
        </div>
      </section>

      <aside class="panel" aria-labelledby="how-it-works">
        <h3 id="how-it-works">How the first weeks usually go</h3>
        <ol style="color:var(--muted);margin-top:8px">
          <li>First session: assessment and priorities.</li>
          <li>Weeks 2–6: practical experiments and adjustments.</li>
          <li>After 6 sessions: review progress and choose next steps.</li>
        </ol>

        <div style="margin-top:12px">
          <strong>Quick price guide</strong>
          <div style="margin-top:8px;color:var(--muted)">
            Single session: <span id="aside-price">$150</span><br>
            Focus Series (6): <span class="muted">Package pricing available in Rates</span>
          </div>
        </div>

        <div style="margin-top:12px">
          <strong>Contact</strong>
          <div style="color:var(--muted);margin-top:6px">Phone: {{PHONE}}<br>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        </div>
      </aside>
    </div>
  </main>

  <script>
    // Mood-to-method for booking page
    (function(){
      const buttons = Array.from(document.querySelectorAll('.moods button'));
      const label = document.getElementById('method-label');
      const desc = document.getElementById('method-desc');
      const price = document.getElementById('method-price');
      const asidePrice = document.getElementById('aside-price');

      const map = {
        overwhelmed: {label:'Grounding visit', desc:'Shorter session to stabilize and create immediate coping steps.', price:120},
        stuck: {label:'6-session Focus Series', desc:'A compact sequence designed to test changes and build momentum.', price:125},
        exhausted: {label:'Extended session', desc:'Longer initial session for deeper review and pacing.', price:180},
        curious: {label:'Exploratory Visit', desc:'A single session to orient and map possibilities.', price:150}
      };

      function update(key, btn){
        buttons.forEach(b=>b.classList.toggle('active', b===btn));
        const pick = map[key];
        // subtle number animation
        const from = parseFloat(price.textContent.replace('$','')) || pick.price;
        const to = pick.price;
        const start = performance.now();
        const dur = 360;
        (function tick(now){
          const t = Math.min(1,(now-start)/dur);
          const val = Math.round(from + (to-from)*t);
          price.textContent = '$' + val;
          asidePrice.textContent = '$' + val;
          if(now-start < dur) requestAnimationFrame(tick);
        })(start);

        label.textContent = 'Suggested: ' + pick.label;
        desc.textContent = pick.desc;
      }

      buttons.forEach(btn=>btn.addEventListener('click', ()=> update(btn.dataset.key, btn)));
      // default
      buttons[0].click();

      // form submission: build a mailto with the details and open user's mail client (no server required)
      window.handleSubmit = function(e){
        e.preventDefault();
        const form = e.target;
        const data = new FormData(form);
        const name = data.get('name') || '';
        const email = data.get('email') || '';
        const phone = data.get('phone') || '';
        const times = data.get('times') || '';
        const notes = data.get('notes') || '';
        const subject = encodeURIComponent('Booking request from ' + name);
        const body = encodeURIComponent('Name: '+name+'\nEmail: '+email+'\nPhone: '+phone+'\nPreferred times: '+times+'\nNotes: '+notes);
        // open mailto to initiate contact; primary CTA URL is fallback link
